---@param parent UnityEngine.Transform 父节点
---@return UnityEngine.GameObject
function XUiLineArithmetic3Game:InstantiateGrid(prefab, parent)
    local go = XUiHelper.Instantiate(prefab, parent)
    if go and self._CellSize then
        local rectTransform = go:GetComponent(typeof(CS.UnityEngine.RectTransform))
        if rectTransform then
            rectTransform.sizeDelta = self._CellSize
        end
    end
