--- 停止所有活动的 tween
function XUiLineArithmetic3Game:StopAllTweens()
    for _, tween in ipairs(self._ActiveTweens) do
        XScheduleManager.UnSchedule(tween)
    end
    self._ActiveTweens = {}
end

--- 创建可追踪的 tween（用于倒放时停止）
---@param duration number 动画时长
---@param onUpdate function 更新回调
---@param onComplete function 完成回调
function XUiLineArithmetic3Game:CreateTween(duration, onUpdate, onComplete)
    local tween
    tween = XUiHelper.Tween(duration, onUpdate, function()
        for index, tweenToRemove in ipairs(self._ActiveTweens) do
            if tweenToRemove == tween then
                table.remove(self._ActiveTweens, index)
                break
            end
        end
        onComplete()
    end)
    if tween then
        self._ActiveTweens[#self._ActiveTweens + 1] = tween
    end
    return tween
end

--- 初始化游戏对象（车头和车厢）
---@param stageId number 关卡ID
function XUiLineArithmetic3Game:InitializeGameObjects(stageId)
    -- 渲染地图格子
    self:RenderMapGrids(stageId)

    -- 获取关卡配置
    local stageConfig = self._Control:GetStageConfig(stageId)
    if not stageConfig then
        XLog.Error("[XUiLineArithmetic3Game] 未找到关卡配置，stageId:", stageId)
        return
    end

    -- 获取车辆配置
    local carConfig = self._Control:GetCarConfig(stageConfig.MapId)
    if not carConfig or not carConfig.Carriages or #carConfig.Carriages == 0 then
        XLog.Error("[XUiLineArithmetic3Game] 未找到车辆配置或车厢为空，mapId:", stageConfig.MapId)
        return
    end

    -- 车头是车厢的第一个参数(cellId)
    local headCharacterId = carConfig.Carriages[1]
    if not headCharacterId then
        XLog.Error("[XUiLineArithmetic3Game] 车厢配置第一个参数为空，mapId:", stageConfig.MapId)
        return
    end

    local headCellConfig = self._Control:GetCellConfigByCharacterId(headCharacterId)
    if not headCellConfig or not headCellConfig.GridName then
        XLog.Error("[XUiLineArithmetic3Game] 未找到车头格子配置，cellId:", headCharacterId)
        return
    end
    local headGridName = headCellConfig.GridName

    -- 获取起点信息
    local startInfo = self._Control:GetStartInfo(stageId)
    if not startInfo then
        XLog.Error("[XUiLineArithmetic3Game] 未找到起点格，stageId:", stageId)
        return
    end

    -- 获取起点的世界坐标
    local startPos = self:GetGridWorldPosition(startInfo.x, startInfo.y)

    -- 创建车厢
    self:CreateCarriages(startPos)

    -- 由于ui排序问题, 需要先创建车厢, 再创建车头, 否则车厢会盖在车头上面
    -- 根据角色id创建车头
    self:CreateHead(headGridName, startPos)

    -- 创建车厢上的初始乘客
    self:CreateCarriagePassengers(startPos)
end

--- 根据GridName创建车头
---@param gridName string 格子名称（如"GridCharacter03"）
---@param position UnityEngine.Vector3 世界坐标
function XUiLineArithmetic3Game:CreateHead(gridName, position)
    -- 根据GridName动态获取预制体
    local prefab = self[gridName]
    if not prefab then
        XLog.Error("[XUiLineArithmetic3Game] 未找到车头预制体:", gridName)
        return
    end

    -- 实例化车头GameObject
    local headGo = self:InstantiateGrid(prefab, self.PanelCharacter)
    headGo.transform:SetPosition(position.x, position.y, position.z)
    self._HeadGrid = XUiLineArithmetic3GridItem.New(headGo, self)
    
    self:InitDirectionIndicators()
end

--- 创建车厢
---@param position UnityEngine.Vector3 起点世界坐标
function XUiLineArithmetic3Game:CreateCarriages(position)
    local game = self._Control:GetGame()
    local carriages = game:GetCarriages()
    if not carriages or #carriages == 0 then return end

    for i = 1, #carriages do
        local carriageGo = self:InstantiateGrid(self.GridCarriage, self.PanelBoard)
        carriageGo.transform.position = position
        self._CarriageGos[i] = carriageGo
    end
end

--- 创建车厢上的初始乘客（从数据层读取 Passenger.Color 与 Passenger.GridName）
---@param position UnityEngine.Vector3 起点世界坐标
function XUiLineArithmetic3Game:CreateCarriagePassengers(position)
    local game = self._Control:GetGame()
    local carriages = game:GetCarriages()
    if not carriages then return end

    for i, carriage in ipairs(carriages) do
        if carriage.Passenger and carriage.Passenger.GridName then
            local carriageGo = self._CarriageGos[i]
            local gridName = carriage.Passenger.GridName
            local characterPrefab = self[gridName]
            if carriageGo and characterPrefab then
                local passengerGo = self:InstantiateGrid(characterPrefab, carriageGo.transform)
                passengerGo.transform:SetLocalPosition(0, 0, 0)

                local passengerGrid = XUiLineArithmetic3GridItem.New(passengerGo, self)
                
                -- 染色乘客（使用数据层颜色）
                if carriage.Passenger.Color then
                    self:UpdatePassengerColor(passengerGrid, carriage.Passenger.Color)
                end

                -- 注册到UID系统，并建立车厢到乘客的映射
                local uid = self:RegisterPassenger(passengerGrid)
                self:SetPassengerUidByCarriage(i, uid)
            end
        end
    end
end

--- 渲染地图格子
---@param stageId number 关卡ID
function XUiLineArithmetic3Game:RenderMapGrids(stageId)
    -- 获取地图配置数据
    local mapData = self._Control:GetMapByStageId(stageId)
    if not mapData or not next(mapData) then
        XLog.Error("[XUiLineArithmetic3Game] 地图数据为空，stageId:", stageId)
        return
    end

    -- 遍历地图的每一行
    for row, rowConfig in pairs(mapData) do
        local y = row
        -- 遍历该行的每一列
        for x, cellId in ipairs(rowConfig.Column) do
            if cellId > 0 then
                -- 获取格子配置
                local cellConfig = self._Control:GetCellConfig(cellId)
                if cellConfig then
                    -- 乘客格配置GridName是空的, 但是依然需要创建角色格
                    -- 如果是乘客格或车站且配置了角色，克隆角色格
                    self:TryCreateCharacterOnGrid(x, y, cellConfig)

                    -- 根据GridName创建格子UI（传递cellConfig用于生成正确的key）
                    if cellConfig.GridName then
                        local gridItem = self:CreateGridElement(x, y, cellConfig.GridName, cellConfig)

                        if not cellConfig.Color or cellConfig.Color == 0 then
                            -- 如果是车站格子，显示车站颜色
                            if gridItem and cellConfig.Type == XLineArithmetic3Enum.GridType.Station then
                                self:UpdateStationColor(x, y, gridItem)
                            end
                        end
                    end
                end
            end
        end
    end
end

--- 尝试在格子上创建角色（仅乘客格和车站支持）
---@param gridGo UnityEngine.GameObject 格子GameObject
---@param cellConfig table 格子配置
function XUiLineArithmetic3Game:TryCreateCharacterOnGrid(x, y, cellConfig)
    if not x or not y or not cellConfig then
        return
    end

    -- 只有乘客格和车站支持 CharacterId
    local GridType = XLineArithmetic3Enum.GridType
    if cellConfig.Type ~= GridType.Passenger and cellConfig.Type ~= GridType.Station then
        return
    end

    -- 检查是否配置了角色
    if not cellConfig.CharacterId or cellConfig.CharacterId <= 0 then
        return
    end

    -- 获取角色配置
    local characterConfig = self._Control:GetCellConfig(cellConfig.CharacterId)
    if not characterConfig or not characterConfig.GridName then
        return
    end

    -- 克隆角色格
    local characterPrefab = self[characterConfig.GridName]
    if characterPrefab then
        local characterGo = self:InstantiateGrid(characterPrefab, self.PanelCharacter)
        local worldPos = self:GetGridWorldPosition(x, y)
        characterGo.transform:SetPosition(worldPos.x, worldPos.y, worldPos.z)

        local characterGrid = XUiLineArithmetic3GridItem.New(characterGo, self)

        -- 更新车站颜色
        self:UpdateStationColor(x, y, characterGrid)

        -- 染色乘客
        self:UpdatePassengerColor(characterGrid, characterConfig.Color)

        
        -- 乘客格使用UID系统管理
        -- if cellConfig.Type == GridType.Passenger then
        local uid = self:RegisterPassenger(characterGrid)
        -- 存储坐标到UID的映射，供BoardCommand初始查找
        local posKey = x .. "_" .. y
        self._PassengerUidByPos = self._PassengerUidByPos or {}
        self._PassengerUidByPos[posKey] = uid

        -- 同时存储到 _GridElements，供上车/下车逻辑使用
        local passengerKey = "Passenger_" .. x .. "_" .. y
        self._GridElements[passengerKey] = characterGrid
        -- end
    end
end

--- 更新车站颜色显示
---@param x number 格子X坐标
---@param y number 格子Y坐标
---@param stationGo XUiLineArithmetic3GridItem 车站GameObject
---@param color number|nil 指定颜色，nil 则从 Game 层读取
function XUiLineArithmetic3Game:UpdateStationColor(x, y, stationGrid, color)
    local stationColor = color
    if stationColor == nil then
        -- 未指定颜色时从 Game 层获取
        local gameMap = self._Control:GetGameMap()
        if not gameMap or not gameMap[y] or not gameMap[y][x] then
            return
        end
        stationColor = gameMap[y][x].StationColor
    end

    -- 先清除旧的颜色节点
    local childCount = stationGrid.Transform.childCount
    for i = childCount - 1, 0, -1 do
        local child = stationGrid.Transform:GetChild(i)
        if child and child.name and string.find(child.name, "GridCharacterColor") then
            CS.UnityEngine.GameObject.Destroy(child.gameObject)
        end
    end

    -- 如果车站有颜色（不是白色），显示颜色节点
    if stationColor and stationColor ~= XLineArithmetic3Enum.Color.White then
        local colorPrefabName = string.format("GridCharacterColor%02d", stationColor)
        local colorPrefab = self[colorPrefabName]

        if colorPrefab then
            local colorRoot = stationGrid.ColorRoot and stationGrid.ColorRoot.transform or stationGrid.Transform
            local colorGo = XUiHelper.Instantiate(colorPrefab, colorRoot)
            colorGo.transform:SetLocalPosition(0, 0, 0)
            colorGo.transform:SetLocalScale(1, 1, 1)
            colorGo.transform:SetAsFirstSibling()
        end
    end
end

--- 批量刷新所有车站的颜色显示
function XUiLineArithmetic3Game:RefreshAllStationColors()
    -- 从Game层获取地图数据
    local gameMap = self._Control:GetGameMap()
    if not gameMap then
        return
    end

    -- 遍历所有格子
    for y, row in pairs(gameMap) do
        for x, gridData in pairs(row) do
            -- 只处理车站类型的格子
            if gridData.Type == XLineArithmetic3Enum.GridType.Station then
                -- 构造车站格子的key
                local key = string.format("%d_%d", x, y)
                local stationGo = self._GridElements[key]

                if stationGo then
                    self:UpdateStationColor(x, y, stationGo)
                end
            end
        end
    end
end

--- 刷新所有乘客颜色显示到 Game 层实际数据（保底刷新）
function XUiLineArithmetic3Game:RefreshAllPassengerColors()
    local gameMap = self._Control:GetGameMap()
    if not gameMap then
        return
    end

    local GridType = XLineArithmetic3Enum.GridType
    for y, row in pairs(gameMap) do
        for x, gridData in pairs(row) do
            if gridData.Passenger and (gridData.Type == GridType.Passenger or gridData.Type == GridType.Station) then
                local passengerUid = self:GetPassengerUidByPos(x, y)
                if passengerUid then
                    local passengerGo = self:GetPassengerByUid(passengerUid)
                    if passengerGo then
                        self:UpdatePassengerColor(passengerGo, gridData.Passenger.Color)
                    end
                end
            end
        end
    end
end

--- 保底刷新所有车站和乘客颜色到 Game 层实际数据
function XUiLineArithmetic3Game:RefreshAllColorsToGameData()
    self:RefreshAllStationColors()
    self:RefreshAllPassengerColors()
end

--- 创建格子UI元素
---@param x number 格子X坐标
---@param y number 格子Y坐标
---@param gridName string 格子名称（如"GridStart"）
---@param cellConfig table 格子配置（可选，用于判断格子类型）
function XUiLineArithmetic3Game:CreateGridElement(x, y, gridName, cellConfig)
    -- 根据格子类型生成不同的缓存key
    local key
    if cellConfig then
        if cellConfig.Type == XLineArithmetic3Enum.GridType.Passenger then
            -- 乘客格使用 "Passenger_x_y" 格式
            key = "PassengerStation_" .. x .. "_" .. y
        elseif cellConfig.Type == XLineArithmetic3Enum.GridType.Character then
            -- 乘客使用 "Passenger_x_y" 格式
            key = "Passenger_" .. x .. "_" .. y
        elseif cellConfig.Type == XLineArithmetic3Enum.GridType.End or
            cellConfig.Type == XLineArithmetic3Enum.GridType.ExtraEnd then
            -- 终点格使用 "End_x_y" 格式
            key = "End_" .. x .. "_" .. y
        else
            -- 其他格子使用默认格式
            key = string.format("%d_%d", x, y)
        end
    else
        -- 如果没有配置，使用默认格式
        key = string.format("%d_%d", x, y)
    end

    -- 如果已经创建过，直接返回
    if self._GridElements[key] then
        return self._GridElements[key]
    end

    -- 根据GridName动态获取预制体
    local prefab = self[gridName]
    if not prefab then
        XLog.Warning("[XUiLineArithmetic3Game] 未找到格子预制体:", gridName)
        return nil
    end

    -- 计算世界坐标
    local position = self:GetGridWorldPosition(x, y)

    -- 创建UI元素
    local gridGo = self:InstantiateGrid(prefab, self.PanelBoard)
    gridGo.transform:SetPosition(position.x, position.y, position.z)
    
    local gridItem = XUiLineArithmetic3GridItem.New(gridGo, self)

    -- 缓存
    self._GridElements[key] = gridItem

    return gridItem
end

--- 将屏幕坐标转换为格子坐标
---@param screenPos UnityEngine.Vector2 屏幕坐标
---@return number|nil, number|nil 格子坐标(x, y)，如果不在有效范围内返回nil
function XUiLineArithmetic3Game:ScreenToGridPosition(screenPos)
    -- 将屏幕坐标转换为PanelEmpty的本地坐标
    local isInRect, v2 = CS.UnityEngine.RectTransformUtility.ScreenPointToLocalPointInRectangle(
        self.PanelEmpty.transform,
        screenPos,
        CS.XUiManager.Instance.UiCamera
    )

    if not isInRect then
        return nil, nil
    end

    -- 获取GridLayoutGroup配置
    local gridLayout = self.PanelEmpty:GetComponent(typeof(CS.UnityEngine.UI.GridLayoutGroup))
    local cellSize = gridLayout.cellSize
    local spacing = gridLayout.spacing

    -- 计算格子坐标（从0开始）
    local gridX = math.floor(v2.x / (cellSize.x + spacing.x))
    local gridY = math.floor(v2.y / (cellSize.y + spacing.y))

    -- 转换为游戏坐标（从1开始）
    local x = gridX + 1
    local y = gridY + 1

    -- 验证坐标是否在地图范围内（9x7）
    if x < 1 or x > 9 or y < 1 or y > 7 then
        return nil, nil
    end

    return x, y
end

--- 刷新已走过路径显示（TraveledPath，使用 GridPath）
function XUiLineArithmetic3Game:RefreshTraveledPathDisplay()
    local game = self._Control:GetGame()
    local traveledPath = game:GetTraveledPath() or {}

    -- 清除多余的路径显示（放回对象池）
    while #self._PathGrids > #traveledPath do
        local pathGrid = table.remove(self._PathGrids)
        if pathGrid then
            self:ReturnPathGridToPool(pathGrid)
        end
    end

    -- 创建/更新路径显示
    for i = 1, #traveledPath do
        local pos = traveledPath[i]
        if self.GridPath and pos then
            -- 如果不存在则从对象池获取
            if not self._PathGrids[i] then
                local pathGrid = self:GetPathGridFromPool()
                if pathGrid then
                    local position = self:GetGridWorldPosition(pos.x, pos.y)
                    pathGrid.GameObject:SetActiveEx(true)
                    pathGrid.Transform:SetPosition(position.x, position.y, position.z)
                    self._PathGrids[i] = pathGrid
                end
            end

            -- 设置路径方向（撤销后重新走时方向可能变化，需要重新设置）
            if self._PathGrids[i] then
                local fromDir, toDir = self:_CalcPathDirections(traveledPath, i)
                if fromDir and toDir then
                    local pathType = self:_CalcPathDirectionType(fromDir, toDir)
                    self:SetPathDirection(self._PathGrids[i], pathType)
                end
            end
        end
    end
end

--- 刷新玩家绘制路径显示（当前 Path，使用 GridPathSelected）
function XUiLineArithmetic3Game:RefreshSelectedPathDisplay()
    local game = self._Control:GetGame()
    local drawingPath = game:GetPath() or {}

    -- 清除多余的路径显示
    while #self._SelectedPathGrids > #drawingPath do
        local pathGo = table.remove(self._SelectedPathGrids)
        if pathGo then
            CS.UnityEngine.GameObject.Destroy(pathGo.gameObject)
        end
    end

    -- 创建缺少的路径显示
    for i = #self._SelectedPathGrids + 1, #drawingPath do
        local pos = drawingPath[i]
        if self.GridPathSelected and pos then
            local pathGo = self:InstantiateGrid(self.GridPathSelected, self.PanelPath)
            local position = self:GetGridWorldPosition(pos.x, pos.y)
            pathGo.transform.position = position
            self._SelectedPathGrids[i] = pathGo
        end
    end
end

--- 清空玩家绘制路径显示
function XUiLineArithmetic3Game:ClearSelectedPathDisplay()
    for _, pathGo in ipairs(self._SelectedPathGrids) do
        if pathGo then
            CS.UnityEngine.GameObject.Destroy(pathGo.gameObject)
        end
    end
    self._SelectedPathGrids = {}
end

--- 取消当前临时路径（松手在 PanelTouch/棋盘外视为无效）
function XUiLineArithmetic3Game:CancelCurrentPath()
    local game = self._Control and self._Control:GetGame() or nil
    if game then
        game:ClearPath()
    end
    self:ClearSelectedPathDisplay()
end

--- 开始画线
---@param eventData PointerEventData 事件数据
function XUiLineArithmetic3Game:OnBeginDrag(eventData)
    -- 动画播放中或回退中禁止操作
    if self._CommandManager:IsPlaying() or self._CommandManager:IsRewinding() then
        return
    end

    local x, y = self:ScreenToGridPosition(eventData.position)
    if not x or not y then
        return
    end

    -- 如果不是undo点，并且不在直线可达范围，直接返回，避免格子选中状态闪烁
    local game = self._Control:GetGame()
    local isUndoTarget = game:IsOnTraveledPath({ x = x, y = y }) and not (game:GetHeadPos() and game:GetHeadPos().x == x and game:GetHeadPos().y == y)
    if not isUndoTarget and not game:CanStraightReach({ x = x, y = y }) then
        return
    end

    game:OnPathAdd({ x = x, y = y })
    self:RefreshSelectedPathDisplay()
end

--- 拖动画线
---@param eventData PointerEventData 事件数据
function XUiLineArithmetic3Game:OnDrag(eventData)
    -- 动画播放中或回退中禁止操作
    if self._CommandManager:IsPlaying() or self._CommandManager:IsRewinding() then
        return
    end

    local x, y = self:ScreenToGridPosition(eventData.position)
    if not x or not y then
        return
    end

    local game = self._Control:GetGame()
    local path = game:GetPath()

    -- 如果不在画线过程中，忽略
    if not path or #path == 0 then
        return
    end

    local lastPos = path[#path]

    -- 如果是同一个格子，忽略
    if lastPos.x == x and lastPos.y == y then
        return
    end

    -- 检查是否回退到上一步
    if #path >= 2 then
        local prevPos = path[#path - 1]
        if prevPos.x == x and prevPos.y == y then
            game:OnPathUndo()
            self:RefreshSelectedPathDisplay()
            return
        end
    end

    -- 尝试添加到路径
    local success = game:OnPathAdd({ x = x, y = y })
    if success then
        self:RefreshSelectedPathDisplay()
    end
end

--- 结束画线
---@param eventData PointerEventData 事件数据
function XUiLineArithmetic3Game:OnEndDrag(eventData)
    -- 动画播放中或回退中禁止操作
    if self._CommandManager:IsPlaying() or self._CommandManager:IsRewinding() then
        return
    end

    local game = self._Control:GetGame()
    -- 松手在 PanelTouch/棋盘外：取消本次临时路径，认为无效
    local endX, endY = self:ScreenToGridPosition(eventData.position)
    if not endX or not endY then
        self:CancelCurrentPath()
        return
    end

    -- 先检查回退：用拖拽终点坐标判断是否命中 TraveledPath 上的历史点
    local traveledPath = game:GetTraveledPath()
    if traveledPath and #traveledPath >= 2 then
        local undoGroupCount = 0
        for i = #traveledPath - 1, 1, -1 do
            if traveledPath[i].x == endX and traveledPath[i].y == endY then
                undoGroupCount = #traveledPath - i
                break
            end
        end
        if undoGroupCount > 0 then
            -- 埋点：记录一次回撤操作（无论撤多少组，都算玩家一次操作）
            if game.OnUndo then
                game:OnUndo(1)
            end
            game:ClearPath()
            self:ClearSelectedPathDisplay()
            -- 隐藏方向指示器（倒放期间）
            self:HideAllDirectionIndicators()
            self._CommandManager:UndoGroups(undoGroupCount, function()
                -- 保底刷新所有车站和乘客颜色到 Game 层实际数据
                self:RefreshAllColorsToGameData()
                -- 刷新星星目标显示（Undo 之后）
                self:UpdateStarTarget()
                -- 刷新方向指示器（倒放完成后显示）
                self:RefreshDirectionIndicators()
            end)
            return
        end
    end

    local path = game:GetPath()
    if not path or #path < 2 then
        self:CancelCurrentPath()
        return
    end

    -- 确认路径并获取指令
    game:ConfirmPath()
    local instructions = game:GetInstructions()

    -- 如果有指令，播放动画
    if instructions and #instructions > 0 then
        self:PlayInstructions(instructions)
    else
        game:ClearPath()
        self:ClearSelectedPathDisplay()
    end
end

--- 播放指令列表
---@param instructions table[] 指令列表
function XUiLineArithmetic3Game:PlayInstructions(instructions)
    if not instructions or #instructions == 0 then
        return
    end

    -- 设置播放状态，禁止玩家操作
    self._CommandManager:SetPlaying(true)

    -- 隐藏方向指示器（动画播放期间）
    self:HideAllDirectionIndicators()

    -- 保存指令队列
    self._InstructionQueue = instructions
    self._CurrentInstructionIndex = 0

    -- 开始播放第一个指令
    self:PlayNextInstruction()
end

--- 播放下一个指令
function XUiLineArithmetic3Game:PlayNextInstruction()
    self._CurrentInstructionIndex = self._CurrentInstructionIndex + 1

    -- 检查是否还有指令
    if self._CurrentInstructionIndex > #self._InstructionQueue then
        -- 所有指令播放完成，结束当前分组
        self._CommandManager:EndGroup()
        -- 关闭播放状态
        self._CommandManager:SetPlaying(false)
        -- 清空路径
        self._Control:GetGame():ClearPath()
        -- 清空玩家绘制路径显示
        self:ClearSelectedPathDisplay()
        -- 刷新已走过路径显示
        self:RefreshTraveledPathDisplay()
        -- 保底刷新所有车站和乘客颜色到 Game 层实际数据
        self:RefreshAllColorsToGameData()
        -- 刷新星星目标显示（所有指令完成后，使用最终状态）
        self:UpdateStarTarget()
        -- 刷新方向指示器（动画播放完成后显示）
        self:RefreshDirectionIndicators()
        -- 检查胜利
        self:CheckVictory()
        return
    end

    -- 播放当前指令
    local instruction = self._InstructionQueue[self._CurrentInstructionIndex]
    local Ins = XLineArithmetic3Enum.Instruction

    -- 遇到 MoveHead 时，结束上一组并开启新一组
    if instruction.Type == Ins.MoveHead then
        if self._CurrentInstructionIndex > 1 then
            self._CommandManager:EndGroup()
        end
        self._CommandManager:BeginGroup()
    end

    local currentIndex = self._CurrentInstructionIndex
    self:PlaySingleInstruction(instruction, function()
        -- 仅在上下车指令执行完成后，按「指令序号」刷新星星目标显示
        if instruction.Type == Ins.Board or instruction.Type == Ins.Disembark then
            self:UpdateStarTarget(currentIndex)
        end
        self:PlayNextInstruction()
    end)
end

--- 检查胜利条件
function XUiLineArithmetic3Game:CheckVictory()
    if self._Control:IsHeadAtEnd() then
        self:OnGameComplete()
    end
end

--- 游戏完成（胜利）
function XUiLineArithmetic3Game:OnGameComplete()
    -- 更新星星目标数据
    self._Control:UpdateStarTarget()

    -- 更新结算描述数据
    self._Control:UpdateSettleDesc()

    -- 弹出结算界面
    self._Control:RequestSettle()
end

--- 播放单个指令（使用 Command 模式）
---@param instruction table 指令数据
---@param onComplete function 完成回调
function XUiLineArithmetic3Game:PlaySingleInstruction(instruction, onComplete)
    local Ins = XLineArithmetic3Enum.Instruction
    local command = self:CreateCommand(instruction)

    if command then
        self._CommandManager:ExecuteCommand(command, onComplete)
    else
        if onComplete then onComplete() end
    end
end

--- 根据指令创建对应的 Command 对象
---@param instruction table 指令数据
---@return XLineArithmetic3Command
function XUiLineArithmetic3Game:CreateCommand(instruction)
    local Ins = XLineArithmetic3Enum.Instruction

    if instruction.Type == Ins.MoveHead then
        local MoveHeadCommand = require("XModule/XLineArithmetic3/XLineArithmetic3MoveHeadCommand")
        return MoveHeadCommand.New(self, instruction.X, instruction.Y, instruction.HeadPosBefore)
    elseif instruction.Type == Ins.Board then
        local BoardCommand = require("XModule/XLineArithmetic3/XLineArithmetic3BoardCommand")
        return BoardCommand.New(self, instruction.GridX, instruction.GridY, instruction.CarriageIndex, instruction.Color, instruction.GridPassengerBefore)
    elseif instruction.Type == Ins.Disembark then
        local DisembarkCommand = require("XModule/XLineArithmetic3/XLineArithmetic3DisembarkCommand")
        return DisembarkCommand.New(self, instruction.GridX, instruction.GridY, instruction.CarriageIndex, instruction.Color, instruction.CarriagePassengerBefore)
    elseif instruction.Type == Ins.ActivateEnd then
        local ActivateEndCommand = require("XModule/XLineArithmetic3/XLineArithmetic3ActivateEndCommand")
        return ActivateEndCommand.New(self, instruction.GridX, instruction.GridY)
    elseif instruction.Type == Ins.DyePassenger then
        local DyePassengerCommand = require("XModule/XLineArithmetic3/XLineArithmetic3DyePassengerCommand")
        return DyePassengerCommand.New(self, instruction.CarriageIndex, instruction.Color, instruction.PassengerColorBefore)
    elseif instruction.Type == Ins.DyeStationPassenger then
        local DyeStationPassengerCommand = require("XModule/XLineArithmetic3/XLineArithmetic3DyeStationPassengerCommand")
        return DyeStationPassengerCommand.New(self, instruction.GridX, instruction.GridY, instruction.Color, instruction.PassengerColorBefore)
    elseif instruction.Type == Ins.StationColorChanged then
        local StationColorChangedCommand = require("XModule/XLineArithmetic3/XLineArithmetic3StationColorChangedCommand")
        return StationColorChangedCommand.New(self, instruction.GridX, instruction.GridY, instruction.Color, instruction.StationColorBefore)
    elseif instruction.Type == Ins.ChangePassengerEmoj then
        local ChangePassengerEmojCommand = require("XModule/XLineArithmetic3/XLineArithmetic3ChangePassengerEmojCommand")
        return ChangePassengerEmojCommand.New(self, instruction.GridX, instruction.GridY, instruction.CarriageIndex, instruction.Emoj, instruction.EmojBefore, instruction.IsHead)
    end

    return nil
end

--- 处理车头移动指令
---@param x number 目标格子X坐标
---@param y number 目标格子Y坐标
---@param onComplete function 完成回调
function XUiLineArithmetic3Game:OnMoveHead(x, y, onComplete)
    if not self._HeadGrid then
        XLog.Warning("[XUiLineArithmetic3Game] 车头未初始化")
        if onComplete then onComplete() end
        return
    end

    -- 保存移动前的 UI 状态
    self:SaveUIState()

    -- 获取目标格子的世界坐标
    local targetPos = self:GetGridWorldPosition(x, y)

    -- 获取车头当前位置（车厢的目标位置）
    local headStartPos = self._HeadGrid.transform.position

    -- 记录每个车厢的起始位置
    local carriageStartPositions = {}
    for i, carriageGo in ipairs(self._CarriageGos) do
        if carriageGo then
            carriageStartPositions[i] = carriageGo.transform.position
        end
    end

    -- 使用可追踪的 tween 同步移动车头和车厢
    local duration = 0.3
    self:CreateTween(duration, function(progress)
        -- 车头移动：从当前位置到目标位置
        local headCurrentPos = CS.UnityEngine.Vector3.Lerp(headStartPos, targetPos, progress)
        self._HeadGrid.Transform:SetPosition(headCurrentPos.x, headCurrentPos.y, headCurrentPos.z)

        -- 车厢移动：从各自位置到车头的起始位置
        for i, carriageGo in ipairs(self._CarriageGos) do
            if carriageGo and carriageStartPositions[i] then
                local carriageCurrentPos = CS.UnityEngine.Vector3.Lerp(carriageStartPositions[i], headStartPos, progress)
                carriageGo.transform.position = carriageCurrentPos
            end
        end
    end, function()
        if onComplete then onComplete() end
    end)
end

--- 车厢跟随车头移动（移动到车头的上一个位置）
---@param prevHeadPos UnityEngine.Vector3 车头移动前的位置
function XUiLineArithmetic3Game:MoveCarriagesToHead(prevHeadPos)
    -- 所有车厢移动到车头的上一个位置（跟在车头后一格）
    for _, carriageGo in ipairs(self._CarriageGos) do
        if carriageGo then
            carriageGo.transform.position = prevHeadPos
        end
    end
end

--- 处理乘客上车指令
---@param gridX number 格子X坐标
---@param gridY number 格子Y坐标
---@param carriageIndex number 车厢索引
---@param color number 乘客颜色
---@param onComplete function 完成回调
function XUiLineArithmetic3Game:OnBoard(gridX, gridY, carriageIndex, color, onComplete)
    -- 获取格子上的乘客GameObject
    local passengerKey = "Passenger_" .. gridX .. "_" .. gridY
    local passengerGo = self._GridElements[passengerKey]

    if not passengerGo then
        XLog.Warning("[XUiLineArithmetic3Game] 格子上没有乘客: (" .. gridX .. ", " .. gridY .. ")")
        if onComplete then onComplete() end
        return
    end

    -- 获取目标车厢
    local carriageGo = self._CarriageGos[carriageIndex]
    if not carriageGo then
        XLog.Warning("[XUiLineArithmetic3Game] 车厢未初始化: " .. carriageIndex)
        if onComplete then onComplete() end
        return
    end

    -- 获取车厢的世界坐标
    local targetPos = carriageGo.transform.position

    -- 获取乘客当前位置
    local startPos = passengerGo.transform.position

    -- 使用缓动动画移动乘客到车厢
    local duration = 0.2
    XUiHelper.Tween(duration, function(progress)
        local currentPos = CS.UnityEngine.Vector3.Lerp(startPos, targetPos, progress)
        passengerGo.transform.position = currentPos
    end, function()
        -- 动画完成后，隐藏乘客GameObject
        passengerGo:SetActive(false)

        -- 调用完成回调
        if onComplete then onComplete() end
    end)
end

--- 处理乘客下车指令
---@param gridX number 格子X坐标
---@param gridY number 格子Y坐标
---@param carriageIndex number 车厢索引
---@param _color number 乘客颜色（未使用，因为重用已存在的GameObject）
---@param onComplete function 完成回调
function XUiLineArithmetic3Game:OnDisembark(gridX, gridY, carriageIndex, _color, onComplete)
    -- 获取车厢
    local carriageGo = self._CarriageGos[carriageIndex]
    if not carriageGo then
        XLog.Warning("[XUiLineArithmetic3Game] 车厢未初始化: " .. carriageIndex)
        if onComplete then onComplete() end
        return
    end

    -- 获取已存在的乘客GameObject（初始化时创建的）
    local passengerKey = "Passenger_" .. gridX .. "_" .. gridY
    local passengerGrid = self._GridElements[passengerKey]

    if not passengerGrid then
        XLog.Warning("[XUiLineArithmetic3Game] 格子上没有乘客GameObject: (" .. gridX .. ", " .. gridY .. ")")
        if onComplete then onComplete() end
        return
    end

    -- 重新激活乘客GameObject（上车时被隐藏了）
    passengerGrid.GameObject:SetActive(true)

    -- 获取目标格子的世界坐标
    local targetPos = self:GetGridWorldPosition(gridX, gridY)

    -- 获取车厢当前位置作为起点
    local startPos = carriageGo.transform.position

    -- 设置初始位置为车厢位置
    passengerGrid.Transform:SetPosition(startPos.x, startPos.y, startPos.z)

    -- 使用缓动动画移动乘客到格子
    local duration = 0.2
    XUiHelper.Tween(duration, function(progress)
        local currentPos = CS.UnityEngine.Vector3.Lerp(startPos, targetPos, progress)
        passengerGrid.transform:SetPosition(currentPos.x, currentPos.y, currentPos.z)
    end, function()
        -- 更新乘客颜色（染色后的颜色）
        self:UpdatePassengerColor(passengerGrid, _color)

        -- 调用完成回调
        if onComplete then onComplete() end
    end)
end

--- 处理激活终点格指令
---@param gridX number 格子X坐标
---@param gridY number 格子Y坐标
---@param onComplete function 完成回调
function XUiLineArithmetic3Game:OnActivateEnd(gridX, gridY, onComplete)
    -- 获取终点格GameObject
    local endKey = "End_" .. gridX .. "_" .. gridY
    local endGo = self._GridElements[endKey]

    if not endGo then
        XLog.Warning("[XUiLineArithmetic3Game] 终点格未找到: (" .. gridX .. ", " .. gridY .. ")")
        if onComplete then onComplete() end
        return
    end

    -- 播放激活动画：缩放效果
    local originalScale = endGo.transform.localScale
    local targetScale = originalScale * 1.2

    local duration = 0.3
    XUiHelper.Tween(duration, function(progress)
        local scale = CS.UnityEngine.Vector3.Lerp(originalScale, targetScale, progress)
        endGo.transform.localScale = scale
    end, function()
        -- 恢复原始大小
        endGo.transform.localScale = originalScale

        -- 调用完成回调
        if onComplete then onComplete() end
    end)
end

--- 更新乘客颜色显示
---@param characterGrid XUiLineArithmetic3GridItem 乘客GameObject
---@param color number 颜色值
function XUiLineArithmetic3Game:UpdatePassengerColor(characterGrid, color)
    if not characterGrid then
        return
    end

    -- 先清除旧的颜色节点
    local childCount = characterGrid.Transform.childCount
    for i = childCount - 1, 0, -1 do
        local child = characterGrid.Transform:GetChild(i)
        if child and child.name and string.find(child.name, "GridCharacterColor") then
            CS.UnityEngine.GameObject.Destroy(child.gameObject)
        end
    end

    -- 如果颜色是白色，不需要添加颜色节点
    if not color or color == XLineArithmetic3Enum.Color.White then
        return
    end

    -- 构建颜色预制体名称（如color=2对应GridCharacterColor02）
    local colorPrefabName = string.format("GridCharacterColor%02d", color)
    local colorPrefab = self[colorPrefabName]

    if not colorPrefab then
        XLog.Warning("[XUiLineArithmetic3Game] 颜色预制体未找到: " .. colorPrefabName)
        return
    end

    -- 克隆颜色节点并挂到乘客上
    local colorRoot = characterGrid.ColorRoot and characterGrid.ColorRoot.transform or characterGrid.Transform
    local colorGo = XUiHelper.Instantiate(colorPrefab, colorRoot)
    colorGo.transform:SetLocalPosition(0, 0, 0)
    colorGo.transform:SetLocalScale(1, 1, 1)
    colorGo.transform:SetAsFirstSibling()

end

--- 更新乘客表情显示
---@param gridItem UnityEngine.GameObject 乘客GameObject
---@param emoj number 表情枚举值 (XLineArithmetic3Enum.Emoj)
function XUiLineArithmetic3Game:UpdatePassengerEmoj(gridItem, emoj)
    if not gridItem then
        return
    end

    -- 遍历所有表情节点，只激活目标表情
    if not XTool.IsTableEmpty(self._EmojiMap) then
        for emojValue, nodeName in pairs(self._EmojiMap) do
            local child = gridItem[nodeName]
            if child then
                child.gameObject:SetActiveEx(emojValue == emoj)
            end
        end
    end
end

--- 根据当前关卡配置刷新指引格子（用于下一关/重新挑战后刷新为新区块 tips）
function XUiLineArithmetic3Game:RefreshTipGridsToCurrentStage()
    if not self.PanelTips or not self.GridTips then
        return
    end

    -- 若存在 BtnTips，则仅在按钮处于选中状态时才刷新/显示指引；
    -- 按钮未选中时，确保隐藏指引
    if self.BtnTips then
        local isOn = self.BtnTips:GetToggleState()
        if not isOn then
            self.PanelTips.gameObject:SetActiveEx(false)
            self:ClearTipGrids()
            return
        end
    end
    self:ClearTipGrids()
    local configs = self._Control:GetHelpConfigsForCurrentStage()
    if not configs or #configs == 0 then
        self.PanelTips.gameObject:SetActiveEx(false)
        return
    end
    local parent = self.PanelTips
    for i = 1, #configs do
        local cfg = configs[i]
        local x = cfg.X
        local y = cfg.Y
        if x and y then
            local tipGo = CS.UnityEngine.GameObject.Instantiate(self.GridTips, parent.transform)
            tipGo.gameObject:SetActiveEx(true)
            -- 设置序号文本（TxtNum）
            local txtNum = XUiHelper.TryGetComponent(tipGo.transform, "TxtNum", "Text")
            if txtNum then
                txtNum.text = tostring(i)
            end
            local worldPos = self:GetGridWorldPosition(x, y)
            tipGo.transform.position = worldPos
            self._TipGrids[#self._TipGrids + 1] = tipGo
        end
    end
    self.PanelTips.gameObject:SetActiveEx(true)
end

--- 点击指引按钮：根据当前关卡 mapId 获取帮助配置，在 PanelTips 层对应 (X,Y) 位置创建 GridTips 指引路线
function XUiLineArithmetic3Game:OnClickBtnTips()
    if not self.PanelTips or not self.GridTips then
        return
    end
    local isOn = self.BtnTips:GetToggleState()
    if isOn then
        self.PanelTips.gameObject:SetActiveEx(true)
        self:RefreshTipGridsToCurrentStage()

        -- 埋点：标记使用过提示
        local game = self._Control:GetGame()
        if game then
            game:MarkUsedTips()
        end
    else
        self.PanelTips.gameObject:SetActiveEx(false)
        self:ClearTipGrids()
    end
end

--- 清除当前所有指引格子
function XUiLineArithmetic3Game:ClearTipGrids()
    for _, go in ipairs(self._TipGrids) do
        if go then
            CS.UnityEngine.GameObject.Destroy(go.gameObject)
        end
    end
    self._TipGrids = {}
end

--- 获取格子的世界坐标
---@param x number 格子X坐标（1-9）
---@param y number 格子Y坐标（1-7）
---@return UnityEngine.Vector3 世界坐标
function XUiLineArithmetic3Game:GetGridWorldPosition(x, y)
    if not self.PanelEmpty then
        XLog.Error("[XUiLineArithmetic3Game] PanelEmpty is nil")
        return CS.UnityEngine.Vector3.zero
    end

    -- 获取 GridLayoutGroup 组件
    local gridLayout = self.PanelEmpty:GetComponent(typeof(CS.UnityEngine.UI.GridLayoutGroup))
    if not gridLayout then
        XLog.Error("[XUiLineArithmetic3Game] GridLayoutGroup not found on PanelEmpty")
        return CS.UnityEngine.Vector3.zero
    end

    -- 读取格子大小和间距
    local cellSize = gridLayout.cellSize
    local spacing = gridLayout.spacing

    -- 计算格子的本地坐标
    -- (1,1) 是左下角，X从左到右(1-9)，Y从下到上(1-7)
    -- 转换为从0开始的索引
    local indexX = x - 1
    local indexY = y - 1

    -- 计算本地位置（左下角为原点）
    local localX = indexX * (cellSize.x + spacing.x) + cellSize.x / 2
    local localY = indexY * (cellSize.y + spacing.y) + cellSize.y / 2

    -- 创建本地坐标向量
    local localPos = CS.UnityEngine.Vector3(localX, localY, 0)

    -- 转换为世界坐标（RectTransform 用 .transform 调用 TransformPoint）
    local worldPos = self.PanelEmpty.transform:TransformPoint(localPos)
    return worldPos
end

--- 更新星星目标显示
--- 星1用固定 GridTarget01，星2、3用 GridTarget02 动态创建（动态长度）
---@param step number|nil 指令步数（用于按动画进度预览星星状态）
function XUiLineArithmetic3Game:UpdateStarTarget(step)
    self._Control:UpdateStarTarget(step)

    local uiData = self._Control:GetUiData()
    local stars = uiData.StarDescData
    -- ui逻辑: 第四颗星作为隐藏星
    local starAmount = math.min(3, #stars)

    -- 星1：固定 GridTarget01
    if starAmount >= 1 and self._StarGrid01 then
        self._StarGrid01:Open()
        self._StarGrid01:Update(stars[1])
    elseif self._StarGrid01 then
        self._StarGrid01:Close()
    end

    -- 星2、3：动态长度，从 GridTarget02 实例化
    for i = 2, starAmount do
        local starDesc = stars[i]
        local uiGrid = self._StarGrids[i]
        if not uiGrid then
            local ui = CS.UnityEngine.GameObject.Instantiate(self.GridTarget02, self.GridTarget02.parent)
            uiGrid = XUiLineArithmetic3GameGridTarget.New(ui, self)
            self._StarGrids[i] = uiGrid
        end
        uiGrid:Open()
        uiGrid:Update(starDesc)
    end
    for i = starAmount + 1, #self._StarGrids do
        local uiGrid = self._StarGrids[i]
        uiGrid:Close()
    end
end

--- 更新事件描述显示
function XUiLineArithmetic3Game:UpdateGridDesc()
    self._Control:UpdateGridDesc()
    local uiData = self._Control:GetUiData()
    local gridDescData = uiData.GridDescData

    for i = 1, #gridDescData do
        local gridDesc = gridDescData[i]
        local uiGrid = self._GridDesc[i]
        if not uiGrid then
            local ui = CS.UnityEngine.GameObject.Instantiate(self.SpecialGrid, self.SpecialGrid.parent)
            uiGrid = XUiLineArithmetic3GameGridDetail.New(ui, self)
            self._GridDesc[i] = uiGrid
        end
        uiGrid:Open()
        uiGrid:Update(gridDesc)
    end
    for i = #gridDescData + 1, #self._GridDesc do
        local uiGrid = self._GridDesc[i]
        uiGrid:Close()
    end
end

--[[
-- GridPath 路，玩家划线经过时，复制一个它，把它放在对应的格子上
-- GridObstacle 障碍，无法通过
-- GridStart 起点
-- GridCharacter01 - GridCharacter05 角色（乘客），也是车头
-- GridCharacterColor01 - GridCharacterColor07 颜色节点，当角色染色，或者车站染色时，把它放在对应的格子上
-- GridEnd01 - GridEnd06 额外终点格
-- GridEnd07 终点格，到达后结束游戏
-- GridStation01 - GridStation07 车站
-- GridCarriage 车厢，开局按照配置复制在角色底下，和角色（车头）重叠，角色移动后，跟随角色移动

-- PanelEmpty 这是一个unity的GridLayoutGroup，读取它的坐标和CellSize，还有StartCorner，StartAxis等参数，可以以此计算棋盘上每个格子的位置，确定格子坐标
    对应棋盘数据9*7
--]]

--============================================================================
-- 方向指示器相关方法
--============================================================================

--- 初始化方向指示器引用（从车头GameObject中获取四个方向的节点）
function XUiLineArithmetic3Game:InitDirectionIndicators()
    if not self._HeadGrid then
        return
    end

    local Direction = XLineArithmetic3Enum.Direction
    
    self._DirectionIndicators[Direction.Up] = self._HeadGrid.up
    self._DirectionIndicators[Direction.Left] = self._HeadGrid.Left
    self._DirectionIndicators[Direction.Down] = self._HeadGrid.down
    self._DirectionIndicators[Direction.Right] = self._HeadGrid.Right

    -- 初始隐藏所有方向指示器
    self:HideAllDirectionIndicators()
end

--- 刷新方向指示器显示（根据可移动方向）
function XUiLineArithmetic3Game:RefreshDirectionIndicators()
    -- 如果正在播放动画或倒放，隐藏所有方向指示器
    if self._CommandManager:IsPlaying() or self._CommandManager:IsRewinding() then
        self:HideAllDirectionIndicators()
        return
    end

    -- 获取可移动方向列表
    local movableDirections = self._Control:GetMovableDirections()

    -- 先隐藏所有方向指示器
    self:HideAllDirectionIndicators()

    -- 显示可移动方向的指示器
    for _, data in ipairs(movableDirections) do
        local direction = data.direction
        local indicator = self._DirectionIndicators[direction]
        if indicator then
            indicator.gameObject:SetActiveEx(true)
        end
    end
end

--- 隐藏所有方向指示器
function XUiLineArithmetic3Game:HideAllDirectionIndicators()
    for _, indicator in pairs(self._DirectionIndicators) do
        if indicator then
            indicator.gameObject:SetActiveEx(false)
        end
    end
end

