--- 设置路径格子的方向显示
---@param pathGrid XUiLineArithmetic3GridItem 路径格子GameObject
---@param pathDirection number PathDirection 路径方向类型
function XUiLineArithmetic3Game:SetPathDirection(pathGrid, pathDirection)
    if not pathGrid then
        return
    end

    local PathDirectionType = self._PathDirectionType
    local dirType = self._PathDirection2Type[pathDirection]

    -- 根据类型显示对应指示器
    local isStraight = dirType == PathDirectionType.StraightLine
    if pathGrid.Indicator_VRight then
        pathGrid.Indicator_VRight.gameObject:SetActiveEx(isStraight)
    end
    if pathGrid.Indicator_VUpHalf then
        pathGrid.Indicator_VUpHalf.gameObject:SetActiveEx(not isStraight)
    end
    if pathGrid.Indicator_VRightHalf then
        pathGrid.Indicator_VRightHalf.gameObject:SetActiveEx(not isStraight)
    end

    -- 从配置表获取旋转和缩放
    local config = self._PathDirectionConfig[pathDirection]
    local zRotation = config and config[1] or 0
    local xScale = config and config[2] or 1

    -- 应用旋转和缩放到 IndicatorRoot
    if pathGrid.IndicatorRoot then
        pathGrid.IndicatorRoot:SetEulerRotation(0, 0, zRotation)
        pathGrid.IndicatorRoot:SetLocalScale(xScale, 1, 1)
    end
end

--- 计算路径方向类型（根据来向和去向）
---@param fromDirection number 来向
---@param toDirection number 去向
---@return number PathDirection
function XUiLineArithmetic3Game:_CalcPathDirectionType(fromDirection, toDirection)
    local Direction = XLineArithmetic3Enum.Direction
    local PathDirection = XLineArithmetic3Enum.PathDirection

    -- 直线情况
    if fromDirection == Direction.Left and toDirection == Direction.Right then
        return PathDirection.LeftToRight
    end
    if fromDirection == Direction.Right and toDirection == Direction.Left then
        return PathDirection.RightToLeft
    end
    if fromDirection == Direction.Up and toDirection == Direction.Down then
        return PathDirection.UpToDown
    end
    if fromDirection == Direction.Down and toDirection == Direction.Up then
        return PathDirection.DownToUp
    end

    -- 转弯情况
    if fromDirection == Direction.Up and toDirection == Direction.Left then
        return PathDirection.TurnFromUpToLeft
    end
    if fromDirection == Direction.Up and toDirection == Direction.Right then
        return PathDirection.TurnFromUpToRight
    end
    if fromDirection == Direction.Down and toDirection == Direction.Left then
        return PathDirection.TurnFromDownToLeft
    end
    if fromDirection == Direction.Down and toDirection == Direction.Right then
        return PathDirection.TurnFromDownToRight
    end
    if fromDirection == Direction.Left and toDirection == Direction.Up then
        return PathDirection.TurnFromLeftToUp
    end
    if fromDirection == Direction.Left and toDirection == Direction.Down then
        return PathDirection.TurnFromLeftToDown
    end
    if fromDirection == Direction.Right and toDirection == Direction.Up then
        return PathDirection.TurnFromRightToUp
    end
    if fromDirection == Direction.Right and toDirection == Direction.Down then
        return PathDirection.TurnFromRightToDown
    end

    -- 默认返回
    return PathDirection.LeftToRight
end

--- 计算路径点i的来向和去向
---@param path table 路径点列表
---@param index number 当前点索引
---@return number|nil, number|nil fromDirection, toDirection
function XUiLineArithmetic3Game:_CalcPathDirections(path, index)
    if not path or #path < 2 then
        return nil, nil
    end

    local current = path[index]
    local fromDir, toDir = nil, nil

    -- 计算去向（当前点到下一点的方向）
    if index < #path then
        local nextPos = path[index + 1]
        toDir = self:_GetDirection(current, nextPos)
    end

    -- 计算来向（上一点相对于当前点的位置方向，即来源方向）
    if index > 1 then
        local prevPos = path[index - 1]
        fromDir = self:_GetDirection(current, prevPos)
    end

    -- 如果是起点或终点，只有一个方向时，用同一个方向
    if fromDir and not toDir then
        toDir = fromDir
    elseif toDir and not fromDir then
        fromDir = toDir
    end

    return fromDir, toDir
end

--- 根据两点位置计算方向
---@param from table 起点坐标 {x, y}
---@param to table 终点坐标 {x, y}
---@return number Direction
function XUiLineArithmetic3Game:_GetDirection(from, to)
    local Direction = XLineArithmetic3Enum.Direction
    local dx = to.x - from.x
    local dy = to.y - from.y

    if dy > 0 then
        return Direction.Up
    elseif dy < 0 then
        return Direction.Down
    elseif dx < 0 then
        return Direction.Left
    elseif dx > 0 then
        return Direction.Right
    end

    return Direction.Right -- 默认
end

--============================================================================
-- 路径格子对象池相关方法
--============================================================================

--- 从对象池获取路径格子（池为空则创建新的）
---@return XUiLineArithmetic3GridItem
function XUiLineArithmetic3Game:GetPathGridFromPool()
    return self._PathGridPool:GetItemFromPool()
end

--- 将路径格子放回对象池
---@param pathGrid XUiLineArithmetic3GridItem
function XUiLineArithmetic3Game:ReturnPathGridToPool(pathGrid)
    if not pathGrid or not pathGrid.GameObject then
        return
    end

    -- 隐藏对象
    pathGrid.GameObject:SetActiveEx(false)

    self._PathGridPool:ReturnItemToPool(pathGrid)
end


return XUiLineArithmetic3Game
